"""Render already-consumed cohort metrics/costs; never read predictions, truth or models."""
from pathlib import Path
import json,csv,hashlib,datetime
P=Path('/workspace/uwb-swad-loso6-20261108')
def read(n):return json.loads((P/n).read_text())
def sha(n):return hashlib.sha256((P/n).read_bytes()).hexdigest()
def write(n,j):(P/n).write_text(json.dumps(j,ensure_ascii=False,indent=2)+'\n')
def pct(x):return f'{100*x:.6f}%'
def pp(x):return f'{100*x:+.6f}'
def comparison(d,tol):return dict(wins=sum(x>tol for x in d),ties=sum(abs(x)<=tol for x in d),losses=sum(x < -tol for x in d),tolerance=tol)
def main():
 s=read('SUMMARY.json');assert (P/'FINALIZE_ONCE.lock').exists() and s['finalizer_invocations']==1
 plan=read('DEVELOPMENT_PROTOCOL.json');tol=plan['spending_gate']['tolerance'];assert tol==1e-12
 assert not s['cohort_spending_gate_passed'] and s['primary_arm']=='swad'
 original=sha('SUMMARY.json');rows=s['all_predeclared_arm_rows'];arms=['baseline','swad','tail','bn_only'];flat=[];classes=[]
 for r in rows:
  for arm in arms:
   m=r[arm];assert m['class_support']==r['baseline']['class_support'] and sum(m['class_support'])==m['n']
   correct=0
   for k,(support,recall) in enumerate(zip(m['class_support'],m['class_recall'])):
    assert (recall is None)==(support==0)
    c=0 if recall is None else round(support*recall)
    if recall is not None:assert abs(support*recall-c)<1e-9
    correct+=c;classes.append(dict(held=r['held'],arm=arm,class_zero_based=k,support=support,recall=recall,correct=c if support else None))
   assert correct==round(m['accuracy']*m['n'])
   flat.append(dict(held=r['held'],arm=arm,n=m['n'],correct=correct,accuracy=m['accuracy'],present_class_macro_recall=m['present_class_macro_recall'],missing_classes=','.join(map(str,m['missing_classes']))))
 with (P/'PARTICIPANT_METRICS.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(flat[0]));w.writeheader();w.writerows(flat)
 with (P/'CLASS_METRICS.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(classes[0]));w.writeheader();w.writerows(classes)
 checks={'SWAD_vs_GAP':(s,s['paired_macro_recall_deltas'])}
 for a in ['tail','bn_only']:
  q=s['descriptive_control_vs_original_GAP'][a];checks[a+'_vs_GAP']=(q,q['paired_macro_recall_deltas'])
  q=s['descriptive_SWAD_vs_matched_controls'][a];checks['SWAD_vs_'+a]=(q,q['paired_macro_recall_deltas'])
 audit={k:dict(raw_summary_strict_positive_wins=q['strict_user_wins'],reported_tolerance_counts=comparison(d,tol),paired_deltas_retained=d) for k,(q,d) in checks.items()}
 assert audit['SWAD_vs_GAP']['reported_tolerance_counts']['wins']==s['strict_user_wins']==3
 assert audit['SWAD_vs_tail']['reported_tolerance_counts']==dict(wins=0,ties=2,losses=4,tolerance=tol)
 write('NUMERICAL_TOLERANCE_AUDIT.json',dict(state='post_score_reporting_audit_only_frozen_summary_and_scorer_unchanged',summary_sha256=original,comparisons=audit,issue='Raw descriptive SWAD-vs-tail strict_user_wins=1 counts +1.1102230246251565e-16 as a win; held1 -2.220446049250313e-16 and held4 +1.1102230246251565e-16 are ties under preregistered1e-12 tolerance and have identical correct-sample counts.',primary_gate_and_primary_wins_unchanged=True,no_new_truth_prediction_model_read=True,no_rescore_or_method_change=True))
 fold_costs={};totals={k:dict(wall=0.,cpu=0.) for k in ['train','replay','output']}
 for h in range(1,7):
  prev=dict(wall=0.,cpu=0.);fold_costs[str(h)]={}
  for stage in ['train','replay','output']:
   t=read(f'folds/held{h}/run/execution/{stage}/TERMINATION.json');assert t['exit_code']==0
   now=t['cumulative'];delta={k:now[k]-prev[k] for k in ['wall','cpu']};fold_costs[str(h)][stage]=delta
   for k in ['wall','cpu']:totals[stage][k]+=delta[k]
   prev=now
 inference={}
 for arm in ['baseline','swad','tail','bn_only']:
  rr=[r for r in s['inference_cost']['rows'] if r['arm']==arm];assert len(rr)==6 and sum(r['n'] for r in rr)==6900
  inference[arm]=dict(n=6900,wall_seconds=sum(r['wall_seconds'] for r in rr),CPU_seconds=sum(r['CPU_seconds'] for r in rr),warmup_wall_seconds=sum(r['warmup_wall_seconds'] for r in rr),warmup_CPU_seconds=sum(r['warmup_CPU_seconds'] for r in rr))
  inference[arm]['wall_ms_per_sample']=1000*inference[arm]['wall_seconds']/6900;inference[arm]['CPU_ms_per_sample']=1000*inference[arm]['CPU_seconds']/6900
 ledger=read('RESOURCE_LEDGER.json');prior={n:dict(wall=ledger['prior_'+n+'6_wall'],cpu=ledger['prior_'+n+'6_cpu']) for n in ['MMD','VREx','Fishr','IRM','GroupDRO']}
 measurements={n:read(n) for n in ['FULL_ARCHIVE_BUILD_EXECUTION.json','FULL_ARCHIVE_PRIVATE_VERIFY_EXECUTION.json','FULL_PRIVATE_INDEX_PREPARATION_EXECUTION.json','INFERENCE_COST_EXECUTION.json','COHORT_SCORE_EXECUTION.json']}
 cost=dict(main_phase=read('STATE.json'),fold_stage_increments=fold_costs,sum_fold_stage_increments=totals,inference=inference,inference_worker=s['inference_cost'],measurements=measurements,canonical_transfer=read('full_backup/TRANSFER_ATTEMPT_RESULTS.json'),prior_complete_method_main_costs=prior,MMD_first_fold_cost_already_included_in_prior_MMD_full_cost_not_added_twice=True,baseline_original_held2to6_training=dict(wall=12416.14960697398,cpu=12416.359542216),baseline_original_held1_isolated_training_cost_not_available=True,scope='Native training/replay/output increments are child-family costs; main phase includes controller overhead. Archive/restore/transfer costs separately retained; overlapped operation wall times must not be called end-to-end research duration; transfer CPU unmeasured, not zero.')
 write('COST_LEDGER.json',cost)
 gate=plan['spending_gate'];analysis=dict(state=s['route'],primary='swad',primary_gate_passed=False,primary_mean_accuracy=s['method']['equal_user_mean_accuracy'],primary_mean_present_macro=s['method']['equal_user_mean_macro_recall'],primary_mean_delta=s['mean_paired_macro_recall_delta'],primary_wins=3,primary_worst_paired_delta=s['worst_paired_macro_recall_delta'],positive_control_evidence_retained_not_promoted=True,tail_control_mean=s['descriptive_control_vs_original_GAP']['tail']['method']['equal_user_mean_macro_recall'],tail_control_mean_delta=s['descriptive_control_vs_original_GAP']['tail']['mean_paired_macro_recall_delta'],tail_control_wins=5,tail_control_is_not_primary_success_or_automatic_method_activation=True,source_summary_sha256=original,numerical_tolerance_reporting_audit='NUMERICAL_TOLERANCE_AUDIT.json',users7_8_labels_used=False,exploratory_historical8_exposure=True,independent_new_user_validation=False,novel_contribution_validated=False,no_new_truth_predictions_models_read=True,observed_utc=datetime.datetime.now(datetime.timezone.utc).isoformat())
 write('FINAL_ANALYSIS.json',analysis)
 out=['# SWAD strict development LOSO6: complete exploratory result','',f"Primary SWAD: {pct(s['method']['equal_user_mean_macro_recall'])} vs GAP {pct(s['baseline']['equal_user_mean_macro_recall'])}, paired mean {pp(s['mean_paired_macro_recall_delta'])}pp, 3/6 improvements. The fixed spending gate failed; close the exact3/6/.3/sourceBN/nativeGAP64/seed20261029 configuration without rescue or rescoring. The positive mean and improved worst-user result remain evidence, even though the gate failed.",'','All six 64-epoch production runs, fresh64 replays, native references, all4 model/output audits and private recovery were frozen before one joint score. Training/validation/test subjects and IDs are disjoint within each fold (testh, validationh%6+1, other4 train). Full617612/all3 signedRMS/native globalBCE/B64/AdamWLookahead/clipping2/64epochs/seed20261029 unchanged. Users7–8 did not choose the method; all8 historically exposed, so this is exploratory development, not independent new-user validation or an originality/causality claim.','', '|Held user|n|GAP accuracy|SWAD accuracy|GAP present macro|SWAD present macro|Paired macro pp|','|---|---:|---:|---:|---:|---:|---:|']
 for r in s['rows']:out.append(f"|{r['held']}|{r['baseline']['n']}|{pct(r['baseline']['accuracy'])}|{pct(r['method']['accuracy'])}|{pct(r['baseline']['present_class_macro_recall'])}|{pct(r['method']['present_class_macro_recall'])}|{pp(r['method']['present_class_macro_recall']-r['baseline']['present_class_macro_recall'])}|")
 out+=['','Accuracy is correct/n. Present-class macro recall averages recall only over classes with nonzero true support; missing-class recall is null, never zero-filled into a12-class macro. Every present class here has100examples, so accuracy and present macro are mathematically equal for each user (last-bit floating values can differ); the definitions remain different. Predicting a missing class still counts as an error. All class supports/recalls are in CLASS_METRICS.csv and the immutable SUMMARY.json.','', '|Held user|Class support, zero-based0..11|Missing classes|','|---|---|---|']
 for r in s['rows']:out.append(f"|{r['held']}|{','.join(map(str,r['method']['class_support']))}|{','.join(map(str,r['method']['missing_classes'])) or 'none'}|")
 out+=['','|Arm|Equal-user accuracy|Equal-user present macro|Worst-user present macro|Pooled sample accuracy|Mean paired macro pp vs GAP|Wins/ties/losses vs GAP|','|---|---:|---:|---:|---:|---:|---|']
 aggregates={'baseline':s['baseline'],'swad':s['method'],**{a:s['descriptive_control_vs_original_GAP'][a]['method'] for a in ['tail','bn_only']}}
 for arm,m in aggregates.items():
  q=None if arm=='baseline' else checks['SWAD_vs_GAP' if arm=='swad' else arm+'_vs_GAP'][0];c=None if q is None else comparison(q['paired_macro_recall_deltas'],tol)
  out.append(f"|{arm}|{pct(m['equal_user_mean_accuracy'])}|{pct(m['equal_user_mean_macro_recall'])}|{pct(m['worst_user_macro_recall'])}|{pct(m['pooled_sample_accuracy'])}|{'reference' if q is None else pp(q['mean_paired_macro_recall_delta'])}|{'reference' if c is None else str(c['wins'])+'/'+str(c['ties'])+'/'+str(c['losses'])}|")
 out+=['',f"Primary spending criteria frozen before scoring: mean gain>=+0.500000pp (actual{pp(s['mean_paired_macro_recall_delta'])}pp, fail), >=4strict improved users (actual3, fail), worst paired delta>=-2.000000pp (actual{pp(s['worst_paired_macro_recall_delta'])}pp, pass). Gate is a spending decision, not the definition of any positive evidence.",'','The predeclared fixed tail averages every post-update parameter snapshot in epochs33–64, followed by the same fixed source-only BN calibration. It shows descriptive positive evidence:94.256313% mean, +0.589141pp,5/6 improved, worst paired-0.250000pp, worst user86.454545%. This is not relabeled as the primary, not a retrospective SWAD pass, and does not activate a new fit or a test-chosen window/seed. BN-only is93.673232% mean (+0.006061pp); controls are descriptive, not a single-seed causal proof. The SWAD primary was averaged by literal author LossValley3/6/.3; the full64-epoch native trajectory continued even after valley death.','', '|Held user|Fixed-tail accuracy / present macro|BN-only accuracy / present macro|','|---|---:|---:|']
 for r in rows:out.append(f"|{r['held']}|{pct(r['tail']['accuracy'])} / {pct(r['tail']['present_class_macro_recall'])}|{pct(r['bn_only']['accuracy'])} / {pct(r['bn_only']['present_class_macro_recall'])}|")
 out+=['', 'SWAD vs fixed tail: mean-0.399495pp,0wins/2ties/4losses under preregistered1e-12 tolerance; worst paired-1.200000pp. Raw SUMMARY strict-positive counter reports1win because held4 differs by+1.110223e-16; held1 differs by-2.220446e-16. Both users have identical correct-sample counts between these arms and are ties at the registered tolerance. NUMERICAL_TOLERANCE_AUDIT.json preserves raw values and reports this numerical artifact. Original SUMMARY/scorer/gate are unchanged; primary3wins/gate failure are unaffected.','', '|Native phase scope|Wall seconds|CPU seconds|','|---|---:|---:|']
 for k,c in totals.items():out.append(f"|{k} across6 folds (incremental)|{c['wall']:.6f}|{c['cpu']:.6f}|")
 main=cost['main_phase'];out +=[f"|Entire original native controller phase|{main['wall']:.6f}|{main['cpu']:.6f}|",'', 'Train/replay include fixed averaging, journaling, validation and source-only calibration; output is the independent output audit. The main row includes controller overhead and is not added again to its components. All prior prep/profile/individual recovery receipts remain retained rather than treated as zero. Original GAPheld2..6 training wall12416.149607/CPU12416.359542s; isolated original GAPheld1 training cost was not separately available and is not invented.','', '|Inference arm (all6users,6900samples each)|Evaluation wall seconds|Evaluation CPU seconds|Wall ms/sample|CPU ms/sample|','|---|---:|---:|---:|---:|']
 for arm,c in inference.items():out.append(f"|{arm}|{c['wall_seconds']:.6f}|{c['CPU_seconds']:.6f}|{c['wall_ms_per_sample']:.6f}|{c['CPU_ms_per_sample']:.6f}|")
 out+=['','One label-free24arm timing worker, B64, rotated order and one64sample warmup per arm: outerprocess wall71.612220/CPU71.991596s, RSS1770816KiB; model/BN state unchanged and all frozen outputs bitwiseequal. Evaluation-only rows exclude checkpoint loading/construction/warmup; warmup and total worker costs are retained in INFERENCE_COST.json. One cohort scorer outerprocess wall15.565638/CPU15.908236s including archive/hash preflight; one consumed lock, no rerun.','', '|Other measured operation|Wall seconds|CPU seconds|','|---|---:|---:|']
 for n,e in measurements.items():out.append(f"|{n}|{e['wall_seconds']:.6f}|{e['user_CPU_seconds']+e['system_CPU_seconds']+e['parent_CPU_seconds']:.6f}|")
 out+=['','Canonical archive1811485836bytes/247owner-onlyparts/2249payload, SHA99453112a56ece88f5d7dca37e6a110978c5202c97d6113012f9aa0526187408. All raw parts and all members verified; original raw/GAP/all6initial chain joined in FULL_COMPOSITE_RECOVERY_INDEX.json. Canonical full extraction/fresh-environment restore was not separately exercised; all6 per-fold physical restores were exercised. Canonical transfer end-to-end4624.658612s includes the orchestration interruption and reconciliation, not pure network; CPU unmeasured.82verified parts retained, knownIDs82/83 reused, uncertain84 exactsearch empty then one explicit upload, untouched85..246 firstattempts complete without failure, all247IDs unique, no automatic retry. Detailed individual fold archive/transfer/restore costs and prior transport faults remain in their receipts. Disk-cache-only eviction and preflight faults remain preserved; all86 original files/2141981100bytes were rechecked before/after and retained.','', '|Prior closed method, complete main phase|Wall seconds|CPU seconds|','|---|---:|---:|']
 for name,c in prior.items():out.append(f"|{name}|{c['wall']:.6f}|{c['cpu']:.6f}|")
 out+=['','MMD prior complete cost already includes its original held1 wall5022.569200421014/CPU5019.332418999999s; do not erase it or add it twice. Historical LTR93.4417%, frozen-class penalty92.7231%, mixed TimeMIL64+Shuffle10094.6290% keep their exact old failed-gate conclusions and different-budget scope. None is substituted for the matched native GAP64 comparator.','', 'The published SWAD reference is Cha et al., NeurIPS2021/arXiv2102.08604; pinned author commit252190eb881169e736beccf51af5caaa5c5cf666. This is an explicit native UWB component transfer, not a full author benchmark reproduction. Focused method/Algorithm1 review is recorded; full appendix-proof/result review is incomplete, and flatness/causal mechanism/originality are not demonstrated. Fixed tail is a predeclared descriptive averaging control; its positive evidence is retained without test-driven promotion.','', 'Exact private prerelease publication8fbd839b3b40f775c8688dd4efbdf5ca749db3f2 was verified before FULL_PRIVATE_RELEASE, before label-free inference and before the only cohort score. Frozen method source and all previous science remain unchanged. Close this exact primary configuration; retain promising control evidence for separately preregistered future research without rerunning or reclassifying this cohort. Existing hourly cloud automation remains enabled and unchanged; no new training is claimed.','']
 (P/'FINAL_REPORT.md').write_text('\n'.join(out));assert sha('SUMMARY.json')==original
 print(json.dumps(dict(primary_mean=s['method']['equal_user_mean_macro_recall'],primary_gain=s['mean_paired_macro_recall_delta'],primary_gate=False,tail_descriptive_mean=analysis['tail_control_mean'],no_new_score=True,raw_summary_unchanged=True)))
if __name__=='__main__':main()
